"""Settings owned by this portable local edition."""

import base64
import json
import os
import shutil
import tempfile
from pathlib import Path

APP_ROOT = Path(__file__).resolve().parents[3]
DATA_ROOT = Path(os.environ.get("PAPERROUTE_DATA_DIR") or APP_ROOT).resolve()
CONFIG_DIR = DATA_ROOT / "config"
POOL_PATH = CONFIG_DIR / "local_models.json"
DEFAULTS = {"request_timeout": 30, "cooldown": 60, "qps": 10, "profiles": []}


def portable_config_path(filename, legacy_path=None):
    path = CONFIG_DIR / filename
    path.parent.mkdir(parents=True, exist_ok=True)
    if (not path.exists() and legacy_path and os.environ.get("PAPERROUTE_NO_LEGACY_IMPORT") != "1"
            and Path(legacy_path).is_file()):
        shutil.copy2(legacy_path, path)
    return path


def atomic_write_json(path, data):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(prefix=path.name + ".", dir=path.parent)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            json.dump(data, stream, ensure_ascii=False, indent=2)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def load_pool_settings(path=None):
    path = Path(path or POOL_PATH)
    if not path.exists():
        return dict(DEFAULTS, profiles=[])
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(data, dict) or not isinstance(data.get("profiles", []), list):
            raise ValueError("invalid format")
        return dict(DEFAULTS, **data)
    except (OSError, ValueError, TypeError) as error:
        raise ValueError("模型池配置读取失败，请检查 config/local_models.json。原文件未覆盖。") from error


def encode_key(value):
    return base64.b64encode(value.encode("utf-8")).decode("ascii") if value else ""


def decode_key(value):
    try:
        return base64.b64decode(value or "", validate=True).decode("utf-8")
    except (ValueError, UnicodeError):
        raise ValueError("模型池中的密钥编码损坏，请在多模型管理中重新填写。") from None


def validate_pool_settings(settings, require_enabled=True):
    from urllib.parse import urlsplit

    for field, low, high in (("request_timeout", 0.1, 600), ("cooldown", 0, 3600), ("qps", 0, 1000)):
        try:
            value = float(settings.get(field, DEFAULTS[field]))
            if not low <= value <= high:
                raise ValueError()
        except (TypeError, ValueError):
            raise ValueError(f"模型池参数 {field} 超出可用范围。") from None
    profiles = settings.get("profiles", [])
    if not isinstance(profiles, list) or any(not isinstance(profile, dict) for profile in profiles):
        raise ValueError("模型池 profiles 必须是模型配置列表。")
    enabled = [profile for profile in profiles if profile.get("enabled", True)]
    if require_enabled and not enabled:
        raise ValueError("请在「多模型管理」中添加并启用至少一个模型。")
    for index, profile in enumerate(enabled, 1):
        url = str(profile.get("base_url", "")).strip()
        parsed = urlsplit(url)
        if parsed.scheme not in ("http", "https") or not parsed.hostname or parsed.username or parsed.password:
            raise ValueError(f"第 {index} 个启用模型需要有效的 HTTP(S) API 地址。")
        try:
            parsed.port
        except ValueError:
            raise ValueError(f"第 {index} 个启用模型的 API 端口无效。") from None
        if not isinstance(profile.get("model"), str) or not profile["model"].strip():
            raise ValueError(f"第 {index} 个启用模型缺少模型名。")
        decode_key(profile.get("api_key", ""))
    return enabled


def save_pool_settings(settings, path=None):
    validate_pool_settings(settings, require_enabled=False)
    atomic_write_json(path or POOL_PATH, settings)
